"""ORD_LINE renumbering invariant migrated from Meridian CRM 4.2."""

from decimal import Decimal, InvalidOperation


def _line_number_key(value: object) -> tuple[int, Decimal | str]:
    """Return a deterministic numeric-first ordering key for LINE_NO values."""
    if value == "":
        return (0, Decimal(0))

    try:
        number = Decimal(str(value))
        if number.is_finite():
            return (0, number)
    except (InvalidOperation, ValueError):
        pass

    # Invalid values are outside the legacy schema contract, but keeping a
    # deterministic fallback makes missing or malformed source data safe.
    return (1, str(value))


def renumber(lines: list[dict]) -> list[dict]:
    """Remove soft-deleted ORD_LINE rows and assign contiguous per-order LINE_NO values."""
    surviving: list[tuple[str, tuple[int, Decimal | str], int, dict]] = []

    for index, row in enumerate(lines):
        if row.get("DEL_FLG", "") == "Y":
            continue

        order_id = str(row.get("ORD_ID", ""))
        line_key = _line_number_key(row.get("LINE_NO", ""))
        surviving.append((order_id, line_key, index, row))

    surviving.sort(key=lambda item: (item[0], item[1], item[2]))

    result: list[dict] = []
    current_order_id: str | None = None
    next_line_no = 0

    for order_id, _, _, row in surviving:
        if order_id != current_order_id:
            current_order_id = order_id
            next_line_no = 1
        else:
            next_line_no += 1

        new_row = dict(row)
        new_row["LINE_NO"] = next_line_no
        result.append(new_row)

    return result
